import Link from "next/link";
import { Reveal } from "./Reveal";
import { Section, SectionTitle, PageHero } from "./primitives";
import { CtaBand } from "./sections";
import { PricingGrid, type PlanCard } from "./PricingGrid";
import { FaqJsonLd, ProductJsonLd } from "./StructuredData";

/**
 * Shared shell for high-intent "host X on a VPS" use-case landing pages.
 *
 * The layout is consistent (premium, converts); the SUBSTANCE — intro prose,
 * why-points, deploy steps, FAQ — comes entirely from per-page `content`, so
 * every page is genuinely unique (not a thin/doorway template). Real plans feed
 * the pricing grid and the Product rich-result. Each page is a server component
 * that fetches `db.plan` and passes it here.
 */
export type UseCaseContent = {
  eyebrow: string;
  /** H1 lead-in (rendered plain) + the gradient highlight word/phrase. */
  title: string;
  highlight: string;
  sub: string;
  /** 1–3 short paragraphs of unique, specific prose. */
  intro: string[];
  /** Section title for the value props, e.g. "Built for Minecraft servers". */
  whyTitle: string;
  why: { title: string; body: string }[];
  /** 3–5 concrete steps to deploy X on the server. */
  steps: { title: string; body: string }[];
  /** Optional sizing hint shown above the plans. */
  specNote?: string;
  faq: { q: string; a: string }[];
  /** Internal links to related pages (crawl + authority flow). */
  related?: { label: string; href: string }[];
};

export function UseCaseLanding({
  content,
  plans,
}: {
  content: UseCaseContent;
  plans: PlanCard[];
}) {
  return (
    <>
      <FaqJsonLd items={content.faq} />
      {plans.length > 0 && <ProductJsonLd plans={plans} />}

      <PageHero
        eyebrow={content.eyebrow}
        title={content.title}
        highlight={content.highlight}
        sub={content.sub}
        primary={{ label: "Deploy now", href: "/register" }}
        secondary={{ label: "See pricing", href: "#pricing" }}
      />

      {/* Intro prose */}
      <Section tone="base" size="md">
        <div className="mx-auto max-w-3xl space-y-4 text-[15px] leading-relaxed text-slate-300">
          {content.intro.map((p, i) => (
            <Reveal as="p" key={i} delay={i * 60}>
              {p}
            </Reveal>
          ))}
        </div>
      </Section>

      {/* Why Nxeon for X */}
      <Section tone="panel" size="md">
        <SectionTitle eyebrow="Why Nxeon" title={content.whyTitle} />
        <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {content.why.map((w, i) => (
            <Reveal key={w.title} delay={i * 60} className="card">
              <h3 className="text-base font-semibold text-white">{w.title}</h3>
              <p className="mt-2 text-sm leading-relaxed text-slate-400">{w.body}</p>
            </Reveal>
          ))}
        </div>
      </Section>

      {/* Deploy steps */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="Get started" title="Up and running in minutes" />
        <ol className="mx-auto mt-10 max-w-3xl space-y-3">
          {content.steps.map((s, i) => (
            <Reveal as="li" key={s.title} delay={i * 60} className="card flex gap-4">
              <span className="flex h-8 w-8 flex-none items-center justify-center rounded-lg bg-brand-500/20 text-sm font-bold text-brand-200">
                {i + 1}
              </span>
              <div>
                <h3 className="text-sm font-semibold text-white">{s.title}</h3>
                <p className="mt-1 text-sm leading-relaxed text-slate-400">{s.body}</p>
              </div>
            </Reveal>
          ))}
        </ol>
      </Section>

      {/* Real plans */}
      {plans.length > 0 && (
        <Section tone="panel" size="lg" id="pricing">
          <SectionTitle eyebrow="Plans" title="Pick your size" sub={content.specNote} />
          <Reveal className="mt-10">
            <PricingGrid plans={plans} />
          </Reveal>
        </Section>
      )}

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {content.faq.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {content.related && content.related.length > 0 && (
        <Section tone="base" size="sm">
          <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
            <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
            {content.related.map((r) => (
              <Link
                key={r.href}
                href={r.href}
                className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
              >
                {r.label}
              </Link>
            ))}
          </div>
        </Section>
      )}

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

