export const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

function JsonLd({ data }: { data: Record<string, unknown> }) {
  return (
    <script
      type="application/ld+json"
      // JSON.stringify output is safe to inline; no user input here.
      dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
    />
  );
}

/** Organization + WebSite (with site search) — rendered once in the root layout. */
export async function OrganizationJsonLd() {
  // sameAs ties "Nxeon" the brand to its social profiles in Google's entity graph —
  // the strongest signal for the brand knowledge panel. Read from admin settings so
  // it stays in sync with the marketing footer; only real http(s) URLs are included.
  let sameAs: string[] = [];
  try {
    const { getSetting } = await import("@/lib/settings");
    const urls = await Promise.all([
      getSetting("social_facebook", ""),
      getSetting("social_instagram", ""),
      getSetting("social_linkedin", ""),
      getSetting("social_youtube", ""),
      getSetting("social_twitter", ""),
      getSetting("social_github", ""),
    ]);
    sameAs = urls.map((u) => u.trim()).filter((u) => /^https?:\/\//i.test(u));
  } catch {
    /* settings unavailable — emit an empty sameAs rather than fail the layout */
  }
  return (
    <>
      <JsonLd
        data={{
          "@context": "https://schema.org",
          "@type": "Organization",
          name: "Nxeon",
          url: APP_URL,
          // A raster logo (min 112x112) is what Google uses for the brand/knowledge
          // panel — an SVG favicon is not eligible. /logo.png is the same mark the
          // portal renders.
          logo: `${APP_URL}/logo.png`,
          description:
            "Cloud VPS hosting, game servers, and domains with instant deployment and full root access.",
          contactPoint: {
            "@type": "ContactPoint",
            contactType: "customer support",
            url: `${APP_URL}/contact`,
          },
          sameAs,
        }}
      />
      <JsonLd
        data={{
          "@context": "https://schema.org",
          "@type": "WebSite",
          name: "Nxeon",
          url: APP_URL,
          potentialAction: {
            "@type": "SearchAction",
            target: `${APP_URL}/domains?q={search_term_string}`,
            "query-input": "required name=search_term_string",
          },
        }}
      />
    </>
  );
}

/** Product + offers for the pricing page. */
export function ProductJsonLd({
  plans,
}: {
  plans: Array<{ name: string; priceCents: number }>;
}) {
  const offers = plans.map((p) => ({
    "@type": "Offer",
    name: `${p.name} VPS`,
    price: (p.priceCents / 100).toFixed(2),
    priceCurrency: "USD",
    availability: "https://schema.org/InStock",
    url: `${APP_URL}/pricing`,
  }));
  return (
    <JsonLd
      data={{
        "@context": "https://schema.org",
        "@type": "Product",
        name: "Nxeon Cloud VPS",
        description:
          "NVMe cloud VPS with full root access, one-click apps, game servers, and an optional dedicated IPv4.",
        brand: { "@type": "Brand", name: "Nxeon" },
        offers: {
          "@type": "AggregateOffer",
          priceCurrency: "USD",
          lowPrice: plans.length ? (Math.min(...plans.map((p) => p.priceCents)) / 100).toFixed(2) : undefined,
          offerCount: plans.length,
          offers,
        },
      }}
    />
  );
}

/**
 * Product + offers for a non-VPS product line (shared hosting, game servers).
 * Kept alongside the VPS-specific ProductJsonLd so each product line can emit a
 * distinct Product entity with its own name/description/url. Prices are in USD
 * dollars (e.g. 3.99); NaN/zero offers are dropped so we never advertise a price
 * we don't charge.
 */
export function ProductOffersJsonLd({
  name,
  description,
  url,
  offers,
}: {
  name: string;
  description: string;
  url: string;
  offers: Array<{ name: string; price: number }>;
}) {
  const priced = offers.filter((o) => Number.isFinite(o.price) && o.price > 0);
  return (
    <JsonLd
      data={{
        "@context": "https://schema.org",
        "@type": "Product",
        name,
        description,
        brand: { "@type": "Brand", name: "Nxeon" },
        offers: {
          "@type": "AggregateOffer",
          priceCurrency: "USD",
          lowPrice: priced.length ? Math.min(...priced.map((o) => o.price)).toFixed(2) : undefined,
          offerCount: priced.length,
          offers: priced.map((o) => ({
            "@type": "Offer",
            name: o.name,
            price: o.price.toFixed(2),
            priceCurrency: "USD",
            availability: "https://schema.org/InStock",
            url,
          })),
        },
      }}
    />
  );
}

/** FAQ rich-result markup. Pass Q/A pairs. */
export function FaqJsonLd({ items }: { items: Array<{ q: string; a: string }> }) {
  return (
    <JsonLd
      data={{
        "@context": "https://schema.org",
        "@type": "FAQPage",
        mainEntity: items.map((i) => ({
          "@type": "Question",
          name: i.q,
          acceptedAnswer: { "@type": "Answer", text: i.a },
        })),
      }}
    />
  );
}

/** Article markup for blog posts. */
export function ArticleJsonLd({
  title,
  description,
  slug,
  published,
  updated,
  author,
  image,
}: {
  title: string;
  description: string;
  slug: string;
  published: string;
  updated: string;
  author: string;
  /** Absolute or root-relative cover image URL, if the post has one. */
  image?: string | null;
}) {
  const url = `${APP_URL}/blog/${slug}`;
  // Normalise a root-relative cover to an absolute URL — Google requires an
  // absolute image URL in the Article markup.
  const imageUrl = image ? (image.startsWith("http") ? image : `${APP_URL}${image}`) : undefined;
  return (
    <JsonLd
      data={{
        "@context": "https://schema.org",
        "@type": "BlogPosting",
        headline: title,
        description,
        url,
        // Ties the rich result to this exact canonical page.
        mainEntityOfPage: { "@type": "WebPage", "@id": url },
        ...(imageUrl ? { image: imageUrl } : {}),
        datePublished: published,
        dateModified: updated,
        author: { "@type": "Organization", name: author },
        publisher: {
          "@type": "Organization",
          name: "Nxeon",
          logo: { "@type": "ImageObject", url: `${APP_URL}/logo.png` },
        },
      }}
    />
  );
}

