export type LocationDef = {
  /** URL slug fragment, e.g. "new-york". */
  slug: string;
  /** Display city, e.g. "New York". */
  city: string;
  /** Human region for prose, e.g. "the US East Coast". */
  region: string;
  /** Longer regional phrase, e.g. "the eastern United States and Canada". */
  regionLong: string;
  /** Adjective for the audience, e.g. "North-American". */
  audience: string;
  /** Nearby cities/markets served well from here. */
  nearby: string[];
  /** One factual sentence about the city's connectivity / why it matters. */
  hub: string;
  /**
   * Whether Nxeon physically operates in this city.
   * - "datacenter": a real Nxeon datacenter (today: Singapore only).
   * - "network":    a city Nxeon markets as part of its network map.
   * - "market":     an audience/market target with no on-site presence yet.
   * Only drives the honesty framing of copy — never invents a datacenter.
   */
  presence: "datacenter" | "network" | "market";
};

export type ServiceDef = {
  key: ServiceKey;
  /** Slug fragment appended after the location, already including "hosting". */
  urlPart: string;
  /** Title-case service label, e.g. "Game Server Hosting". */
  label: string;
  /** Short noun, e.g. "VPS", "game server". */
  noun: string;
  /** The canonical hub page for this service (for internal linking). */
  hub: { label: string; href: string };
};

