/**
 * Slugs already served by a hand-written static page in the marketing group —
 * excluded so the programmatic route never duplicates them (and they aren't
 * double-listed in the sitemap). Static routes win at request time anyway;
 * this keeps the data/sitemap honest.
 */
export const RESERVED_SLUGS = new Set<string>(["singapore-vps-hosting"]);

export type Combo = { location: LocationDef; service: ServiceDef; slug: string };

export const COMBOS: Combo[] = LOCATIONS.flatMap((location) =>
  SERVICES.map((service) => ({
    location,
    service,
    slug: `${location.slug}-${service.urlPart}`,
  })),
).filter((c) => !RESERVED_SLUGS.has(c.slug));

const COMBO_BY_SLUG = new Map(COMBOS.map((c) => [c.slug, c]));

export function findCombo(slug: string): Combo | undefined {
  return COMBO_BY_SLUG.get(slug);
}

/** All programmatic slugs (for generateStaticParams + the sitemap). */
export const LANDING_SLUGS: string[] = COMBOS.map((c) => c.slug);

