const money = (cents: number) => `$${(cents / 100).toFixed(2)}`;

/** Cheapest active plan → "$6.49"-style anchor, or a sane fallback. */
export function fromLabel(plans: LandingPlan[]): string {
  if (!plans.length) return "$6.49";
  return money(Math.min(...plans.map((p) => p.priceCents)));
}

function listPhrase(items: string[]): string {
  if (items.length <= 1) return items.join("");
  return `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
}

/** Honest answer to "where are the servers?" scoped to this location's presence. */
function serverLocationFaq(loc: LocationDef): { q: string; a: string } {
  if (loc.presence === "datacenter") {
    return {
      q: `Where exactly are the ${loc.city} servers located?`,
      a: `Nxeon operates a datacenter in ${loc.city}. It's a single, well-connected location — we don't claim regions we don't run — so what you get is a genuine ${loc.city}-based server, close to ${listPhrase(loc.nearby.slice(0, 3))}.`,
    };
  }
  return {
    q: `Are the servers physically in ${loc.city}?`,
    a: `This page is built for the ${loc.city} market — teams and audiences across ${loc.regionLong}. Our production platform runs from a Singapore datacenter today with regional build-out underway, so at checkout you'll deploy to the nearest available region. If a ${loc.city}-local footprint is a hard requirement for your workload, tell our team before you order and we'll confirm the lowest-latency option for you.`,
  };
}

