        specNote: `For dedicated-grade workloads, start with Pro (8 GB) and move up as needed — the top tiers give you the most cores, RAM and NVMe. Every plan includes a dedicated IP and DDoS protection.`,
        faq: [
          serverLocationFaq(loc),
          { q: "How is this different from a shared VPS?", a: "The larger plans allocate dedicated CPU and memory to you on enterprise NVMe — no oversubscription — so heavy, sustained workloads get consistent performance instead of competing for a shared pool." },
          { q: `What runs well on a ${loc.city} dedicated server?`, a: "Busy databases, high-traffic apps, CI/CD runners, rendering jobs, game-server fleets and anything that needs sustained CPU or lots of RAM close to a " + loc.audience + " audience." },
          { q: "Do I get full root and a dedicated IP?", a: "Yes — full root SSH access, a dedicated IPv4, always-on DDoS protection and a managed firewall come with every plan." },
          { q: "Can I scale up later?", a: "Yes. A one-click resize adds CPU, RAM or disk with no rebuild and no migration, so you can start right-sized and grow as demand does." },
        ],
        related: relatedLinks(combo),
      },
    },
  };

  const built = byService[svc.key];
  return { ...built, breadcrumbName: `${loc.city} ${svc.label}` };
}

/**
 * Internal links: the sibling services in the same city, this service's hub
 * page, and pricing — so crawlers can walk the whole matrix and authority
 * flows between related pages.
 */
function relatedLinks(combo: Combo): { label: string; href: string }[] {
  const { location: loc, service: svc } = combo;
  const siblings = SERVICES.filter((s) => s.key !== svc.key).map((s) => {
    const slug = `${loc.slug}-${s.urlPart}`;
    // Point a reserved (static) sibling at its real static URL; it's the same page.
    return { label: `${loc.city} ${s.label}`, href: `/${slug}` };
  });
  return [...siblings, svc.hub, { label: "Pricing", href: "/pricing" }];
}

import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { UseCaseLanding } from "@/components/marketing/UseCaseLanding";
import { APP_URL } from "@/components/marketing/StructuredData";
import {
  findCombo,
  buildLanding,
  LANDING_SLUGS,
  type LandingPlan,
} from "@/lib/marketing/locationLandings";

/**
 * Programmatic "(location) (service)" marketing landing pages.
 *
 * One data-driven route renders the whole location × service matrix defined in
 * `lib/marketing/locationLandings.ts` — e.g. /london-vps-hosting,
 * /toronto-web-hosting, /frankfurt-game-server-hosting. Any slug not in the
 * matrix falls through to a 404, so this catch-all never shadows the
 * hand-written marketing pages (which win at request time anyway) or invents
 * doorway pages. Real DB plans feed the pricing grid and Product rich-result.
 */

export const dynamic = "force-dynamic";

// Pre-declare the known slugs so Next can enumerate the matrix; unknown slugs
// are rejected in the page/metadata via notFound().
export function generateStaticParams(): Array<{ slug: string }> {
  return LANDING_SLUGS.map((slug) => ({ slug }));
}

async function loadPlans(): Promise<LandingPlan[]> {
  return db.plan.findMany({
    where: { active: true },
    orderBy: { sortOrder: "asc" },
  });
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const combo = findCombo(slug);
  if (!combo) return {};

  const plans = await loadPlans();
  const built = buildLanding(combo, plans);
  const url = `${APP_URL}/${slug}`;

  return {
    title: built.metaTitle,
    description: built.metaDescription,
    alternates: { canonical: `/${slug}` },
    openGraph: {
      type: "article",
      title: built.ogTitle,
      description: built.ogDescription,
      url,
    },
    twitter: {
      card: "summary_large_image",
      title: built.ogTitle,
      description: built.ogDescription,
    },
  };
}

export default async function LocationServiceLandingPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const combo = findCombo(slug);
  if (!combo) notFound();

  const plans = await loadPlans();
  const built = buildLanding(combo, plans);
  const url = `${APP_URL}/${slug}`;

  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
  // the page's place in the site. FAQ + Product JSON-LD are emitted by
  // UseCaseLanding from the same content, so all three rich results are covered.
  const breadcrumb = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
    ],
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
      />
      <UseCaseLanding content={built.content} plans={plans} />
    </>
  );
}

